# ! [doc = " Buffering wrappers for I/O traits"] use split_decls_genesis :: ourprelude :: * ; mod bufreader ; mod bufwriter ; mod linewriter ; mod linewritershim ; #[cfg (test)] mod tests ; #[stable (feature = "bufwriter_into_parts" , since = "1.56.0")] pub use bufwriter :: WriterPanicked ; use linewritershim :: LineWriterShim ; #[stable (feature = "rust1" , since = "1.0.0")] pub use self :: { bufreader :: BufReader , bufwriter :: BufWriter , linewriter :: LineWriter } ; use crate :: io :: Error ; use crate :: { error , fmt } ; #[doc = " An error returned by [`BufWriter::into_inner`] which combines an error that"] #[doc = " happened while writing out the buffer, and the buffered writer object"] #[doc = " which may be used to recover from the condition."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut stream = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // do stuff with the stream"] #[doc = ""] #[doc = " // we want to get our `TcpStream` back, so let's try:"] #[doc = ""] #[doc = " let stream = match stream.into_inner() {"] #[doc = "     Ok(s) => s,"] #[doc = "     Err(e) => {"] #[doc = "         // Here, e is an IntoInnerError"] #[doc = "         panic!(\"An error occurred\");"] #[doc = "     }"] #[doc = " };"] #[doc = " ```"] #[derive (Debug)] #[stable (feature = "rust1" , since = "1.0.0")] pub struct IntoInnerError < W > (W , Error) ; impl < W > IntoInnerError < W > { #[doc = " Constructs a new IntoInnerError"] fn new (writer : W , error : Error) -> Self { Self (writer , error) } #[doc = " Helper to construct a new IntoInnerError; intended to help with"] #[doc = " adapters that wrap other adapters"] fn new_wrapped < W2 > (self , f : impl FnOnce (W) -> W2) -> IntoInnerError < W2 > { let Self (writer , error) = self ; IntoInnerError :: new (f (writer) , error) } #[doc = " Returns the error which caused the call to [`BufWriter::into_inner()`]"] #[doc = " to fail."] #[doc = ""] #[doc = " This error was returned when attempting to write the internal buffer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut stream = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // do stuff with the stream"] #[doc = ""] #[doc = " // we want to get our `TcpStream` back, so let's try:"] #[doc = ""] #[doc = " let stream = match stream.into_inner() {"] #[doc = "     Ok(s) => s,"] #[doc = "     Err(e) => {"] #[doc = "         // Here, e is an IntoInnerError, let's log the inner error."] #[doc = "         //"] #[doc = "         // We'll just 'log' to stdout for this example."] #[doc = "         println!(\"{}\", e.error());"] #[doc = ""] #[doc = "         panic!(\"An unexpected error occurred.\");"] #[doc = "     }"] #[doc = " };"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn error (& self) -> & Error { & self . 1 } #[doc = " Returns the buffered writer instance which generated the error."] #[doc = ""] #[doc = " The returned object can be used for error recovery, such as"] #[doc = " re-inspecting the buffer."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```no_run"] #[doc = " use std::io::BufWriter;"] #[doc = " use std::net::TcpStream;"] #[doc = ""] #[doc = " let mut stream = BufWriter::new(TcpStream::connect(\"127.0.0.1:34254\").unwrap());"] #[doc = ""] #[doc = " // do stuff with the stream"] #[doc = ""] #[doc = " // we want to get our `TcpStream` back, so let's try:"] #[doc = ""] #[doc = " let stream = match stream.into_inner() {"] #[doc = "     Ok(s) => s,"] #[doc = "     Err(e) => {"] #[doc = "         // Here, e is an IntoInnerError, let's re-examine the buffer:"] #[doc = "         let buffer = e.into_inner();"] #[doc = ""] #[doc = "         // do stuff to try to recover"] #[doc = ""] #[doc = "         // afterwards, let's just return the stream"] #[doc = "         buffer.into_inner().unwrap()"] #[doc = "     }"] #[doc = " };"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] pub fn into_inner (self) -> W { self . 0 } #[doc = " Consumes the [`IntoInnerError`] and returns the error which caused the call to"] #[doc = " [`BufWriter::into_inner()`] to fail.  Unlike `error`, this can be used to"] #[doc = " obtain ownership of the underlying error."] #[doc = ""] #[doc = " # Example"] #[doc = " ```"] #[doc = " use std::io::{BufWriter, ErrorKind, Write};"] #[doc = ""] #[doc = " let mut not_enough_space = [0u8; 10];"] #[doc = " let mut stream = BufWriter::new(not_enough_space.as_mut());"] #[doc = " write!(stream, \"this cannot be actually written\").unwrap();"] #[doc = " let into_inner_err = stream.into_inner().expect_err(\"now we discover it's too small\");"] #[doc = " let err = into_inner_err.into_error();"] #[doc = " assert_eq!(err.kind(), ErrorKind::WriteZero);"] #[doc = " ```"] #[stable (feature = "io_into_inner_error_parts" , since = "1.55.0")] pub fn into_error (self) -> Error { self . 1 } #[doc = " Consumes the [`IntoInnerError`] and returns the error which caused the call to"] #[doc = " [`BufWriter::into_inner()`] to fail, and the underlying writer."] #[doc = ""] #[doc = " This can be used to simply obtain ownership of the underlying error; it can also be used for"] #[doc = " advanced error recovery."] #[doc = ""] #[doc = " # Example"] #[doc = " ```"] #[doc = " use std::io::{BufWriter, ErrorKind, Write};"] #[doc = ""] #[doc = " let mut not_enough_space = [0u8; 10];"] #[doc = " let mut stream = BufWriter::new(not_enough_space.as_mut());"] #[doc = " write!(stream, \"this cannot be actually written\").unwrap();"] #[doc = " let into_inner_err = stream.into_inner().expect_err(\"now we discover it's too small\");"] #[doc = " let (err, recovered_writer) = into_inner_err.into_parts();"] #[doc = " assert_eq!(err.kind(), ErrorKind::WriteZero);"] #[doc = " assert_eq!(recovered_writer.buffer(), b\"t be actually written\");"] #[doc = " ```"] #[stable (feature = "io_into_inner_error_parts" , since = "1.55.0")] pub fn into_parts (self) -> (Error , W) { (self . 1 , self . 0) } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W > From < IntoInnerError < W > > for Error { fn from (iie : IntoInnerError < W >) -> Error { iie . 1 } } #[stable (feature = "rust1" , since = "1.0.0")] impl < W : Send + fmt :: Debug > error :: Error for IntoInnerError < W > { } #[stable (feature = "rust1" , since = "1.0.0")] impl < W > fmt :: Display for IntoInnerError < W > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . error () . fmt (f) } }